554	
555	  return {
556	    currentSession,
557	    sessionItems,
558	    isLoading,
559	    createSession,
560	    loadSession,
561	    updateSession,
562	    updateSessionItem,
563	    updateSessionItemByName,
564	    addSessionItem,
565	    removeSessionItem,
566	    finalizeSession,
