93	export function PickingBipModal({ isOpen, onClose, items, requisicaoId, onApply, defaultMode = "bluetooth" }: Props) {
94	  const [aplicados, setAplicados] = useState<BipApplied[]>([]);
95	  const uidsLidosRef = useRef<Set<string>>(new Set());
96	  const [excesso, setExcesso] = useState<ExcessoState>({
97	    open: false, produtoNome: "", pedidoQtd: 0, jaEnviado: 0, etiquetaQtd: 0, sobra: 0,
98	  });
99	
100	  // Transfere separação de outra requisição para esta — chamada automaticamente
101	  // quando o operador bipa uma etiqueta já separada em REQ DIFERENTE da atual.
102	  // Parâmetros explícitos em vez de depender de estado (reseparirDialog removido).
103	  const executarTransferencia = async (uid: string, produtoNome: string, payload: ScannedPayload) => {
104	    try {
105	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
106	      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reseparar", {
107	        p_uid: uid,
108	        p_contexto: {
109	          referencia_tipo: "requisicao",
110	          referencia_id: String(requisicaoId),
111	          payload,
112	        },
113	      });
114	      const rpc = rpcRaw as {
115	        ok: boolean;
116	        erro?: string;
117	        etiqueta?: {
118	          produto_master_id: number;
119	          produto_nome_snapshot?: string | null;
120	          lote_id?: string | null;
121	          quantidade_interna?: number;
122	          embalagem_nome?: string | null;
123	          tipo_embalagem?: string | null;
124	        };
125	      } | null;
126	      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
127	        playErrorSound();
128	        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
129	        return;
130	      }
131	
132	      const scannedPid = rpc.etiqueta.produto_master_id;
133	      const qtyEtiquetaReal = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
134	      const scannedLote = rpc.etiqueta.lote_id ?? null;
135	      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
136	      const scannedTipoEmb = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;
137	      const scannedNome = rpc.etiqueta.produto_nome_snapshot || produtoNome;
138	
139	      const targetReal = items.find((i) => i.masterId === scannedPid);
140	      if (!targetReal) {
141	        uidsLidosRef.current.add(uid);
142	        toast.warning(`${scannedNome} transferido mas NÃO está na lista — registrado como extra`);
143	        return;
144	      }
145	      const scannedQty = calcularIncrementoBip(targetReal.unidade_medida, scannedTipoEmb, qtyEtiquetaReal);
146	      const aplicadosNoItem = aplicados.filter((a) => a.itemId === targetReal.id);
147	      const baseAtual = aplicadosNoItem.length === 0
148	        ? Number(targetReal.quantidade_enviada || 0)
149	        : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(targetReal.quantidade_enviada || 0));
150	      const novaQtdNum = baseAtual + scannedQty;
151	      const batchesNovo: Record<string, number> = { ...(targetReal.selectedBatches || {}) };
152	      if (scannedLote) batchesNovo[scannedLote] = (batchesNovo[scannedLote] || 0) + qtyEtiquetaReal;
153	
154	      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
155	      playSuccessSound();
156	      if (navigator.vibrate) navigator.vibrate(100);
157	      toast.success(`Separação transferida pra esta requisição: ${scannedNome}`);
158	      setAplicados((prev) => [
159	        {
160	          itemId: targetReal.id, produtoNome: targetReal.produto_nome,
161	          uid, qty: scannedQty,
162	          embalagem: scannedEmb, tipoEmbalagem: scannedTipoEmb,
163	          qtyInterna: qtyEtiquetaReal, loteId: scannedLote, bipadoAt: Date.now(),
164	        },
165	        ...prev,
166	      ]);
167	      uidsLidosRef.current.add(uid);
168	    } catch (e) {
169	      playErrorSound();
170	      toast.error(`Erro: ${(e as Error).message}`);
171	    }
172	  };
173	
174	  const handleBip = async (payload: ScannedPayload) => {
175	    if (!payload.uid) {
176	      playErrorSound();
177	      toast.error("Etiqueta sem UID — não rastreável");
178	      return;
179	    }
180	    if (uidsLidosRef.current.has(payload.uid)) {
181	      playErrorSound();
182	      toast.error("Caixa já bipada nesta separação");
183	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
184	      return;
185	    }
186	
187	    // ── Pré-fetch sem mutar status: precisa saber quantidade_interna pra checar excesso
188	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
189	    const { data: pre } = await (supabase
190	      .from("etiquetas_qr") as any)
191	      .select("produto_master_id, produto_nome_snapshot, quantidade_interna, embalagem_nome, tipo_embalagem, lote_id, status")
192	      .eq("uid", payload.uid)
193	      .maybeSingle();
194	
195	    const preEt = pre as
196	      | { produto_master_id: number; produto_nome_snapshot?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; lote_id?: string | null; status?: string }
197	      | null;
198	
199	    const qtyEtiqueta = Number(preEt?.quantidade_interna ?? payload.qty ?? 1);
200	    const tipoEmbEtq = preEt?.tipo_embalagem ?? null;
201	    const pidEstimado = Number(preEt?.produto_master_id ?? payload.pid ?? 0);
202	    const nomeEstimado = preEt?.produto_nome_snapshot || `Produto #${pidEstimado || "?"}`;
203	
204	    // ── Excesso: se item da req achado e nova_qtd > pedido, pedir confirmação
205	    const target = items.find((i) => i.masterId === pidEstimado);
206	    // Regra universal: pedido bate com tipo da etiqueta → +1; senão → +qty_interna
207	    const qtyEstimada = target ? calcularIncrementoBip(target.unidade_medida, tipoEmbEtq, qtyEtiqueta) : qtyEtiqueta;
208	    if (target) {
209	      const aplicadosNoItem = aplicados.filter((a) => a.itemId === target.id);
210	      const baseAtual = aplicadosNoItem.length === 0
211	        ? Number(target.quantidade_enviada || 0)
212	        : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(target.quantidade_enviada || 0));
213	      const novaQtdPrev = baseAtual + qtyEstimada;
214	      if (novaQtdPrev > target.quantidade) {
215	        const sobra = novaQtdPrev - target.quantidade;
216	        const confirmed = await new Promise<boolean>((resolve) => {
217	          setExcesso({
218	            open: true,
219	            produtoNome: target.produto_nome,
220	            pedidoQtd: target.quantidade,
221	            jaEnviado: baseAtual,
222	            etiquetaQtd: qtyEstimada,
223	            sobra,
224	            resolve,
225	          });
226	        });
227	        if (!confirmed) {
228	          // Não chamou RPC ainda — etiqueta segue intacta no banco
229	          return;
230	        }
231	      }
232	    }
233	
234	    // ── RPC = source of truth de validação
235	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
236	    const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
237	      p_uid: payload.uid,
238	      p_etapa: "separacao",
239	      p_contexto: {
240	        referencia_tipo: "requisicao",
241	        referencia_id: String(requisicaoId),
242	        payload,
243	      },
244	    });
245	    if (rpcErr) {
246	      playErrorSound();
247	      toast.error(`Falha no bip: ${rpcErr.message}`);
248	      return;
249	    }
250	    const result = rpcRaw as {
251	      ok: boolean;
252	      erro?: string;
253	      etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; separada_at?: string | null };
254	      alertas?: string[];
255	    };
256	    if (!result?.ok || !result.etiqueta) {
257	      // Caso especial: ja separada → verificar se é na MESMA req (bloqueia) ou em outra (transfere)
258	      const erroLower = (result?.erro || "").toLowerCase();
259	      const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
260	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
261	      const etSep = result?.etiqueta as any;
262	      if (isJaSeparada) {
263	        // Descobre em qual requisição a etiqueta está separada (evento mais recente)
264	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
265	        const { data: evRaw } = await (supabase.from("etiquetas_qr_eventos") as any)
266	          .select("referencia_id")
267	          .eq("etiqueta_uid", payload.uid)
268	          .eq("etapa", "separacao")
269	          .order("created_at", { ascending: false })
270	          .limit(1)
271	          .maybeSingle();
272	        const refSeparada = (evRaw as { referencia_id?: string | null } | null)?.referencia_id ?? null;
273	
274	        // Já separada NESTA requisição → idempotência, não conta de novo
275	        if (refSeparada != null && refSeparada === String(requisicaoId)) {
276	          playErrorSound();
277	          toast.error("Caixa já bipada nesta requisição");
278	          if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
279	          return;
280	        }
281	        // Separada em OUTRA requisição → transfere automático pra esta
282	        await executarTransferencia(payload.uid, etSep?.produto_nome_snapshot || nomeEstimado, payload);
283	        return;
284	      }
285	      playErrorSound();
286	      toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
287	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
288	      return;
289	    }
290	    (result.alertas ?? []).forEach((a) => {
291	      playWarningSound();
292	      toast.warning(a);
293	    });
294	
295	    const scannedPid = result.etiqueta.produto_master_id;
296	    const qtyEtiquetaReal = Number(result.etiqueta.quantidade_interna ?? payload.qty ?? 1);
297	    const scannedLote = result.etiqueta.lote_id ?? null;
298	    const scannedEmb = result.etiqueta.embalagem_nome ?? preEt?.embalagem_nome ?? null;
299	    const scannedNome = result.etiqueta.produto_nome_snapshot || nomeEstimado;
300	
301	    const targetReal = items.find((i) => i.masterId === scannedPid);
302	    if (!targetReal) {
303	      // Item nao esta na lista → silenciosamente registra e segue. Operador
304	      // pode confirmar excesso atraves do AlertDialog se quiser forcar.
305	      // Toast removido (era ruido — sempre aparecia mesmo em fluxo normal de excesso).
306	      uidsLidosRef.current.add(payload.uid);
307	      return;
308	    }
309	
310	    // Regra universal: pedido bate com tipo da etiqueta → +1, senão → +qty real
311	    const scannedTipoEmb = result.etiqueta.tipo_embalagem ?? tipoEmbEtq;
312	    const scannedQty = calcularIncrementoBip(targetReal.unidade_medida, scannedTipoEmb, qtyEtiquetaReal);
313	
314	    const aplicadosNoItem = aplicados.filter((a) => a.itemId === targetReal.id);
315	    const baseAtual = aplicadosNoItem.length === 0
316	      ? Number(targetReal.quantidade_enviada || 0)
317	      : aplicadosNoItem.reduce((acc, a) => acc + a.qty, Number(targetReal.quantidade_enviada || 0));
318	    const novaQtdNum = baseAtual + scannedQty;
319	
320	    // Selected batches sempre rastreia a qty FISICA da etiqueta (pro estoque por lote
321	    // ficar correto independente de unidade do pedido — lote conta unidades reais).
322	    const batchesNovo: Record<string, number> = { ...(targetReal.selectedBatches || {}) };
323	    if (scannedLote) {
324	      batchesNovo[scannedLote] = (batchesNovo[scannedLote] || 0) + qtyEtiquetaReal;
325	    }
326	
327	    try {
328	      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
329	    } catch (e) {
330	      playErrorSound();
331	      toast.error(`Erro ao salvar: ${(e as Error).message}`);
332	      return;
333	    }
334	
335	    playSuccessSound();
336	    if (navigator.vibrate) navigator.vibrate(80);
337	    // Toast mostra "+1 caixa" usando o TIPO da etiqueta (caixa/saco/balde) — nunca "un"
338	    const tipoLabel = (scannedTipoEmb || targetReal.unidade_medida || 'cx').toLowerCase();
339	    toast.success(`${scannedNome} +${scannedQty} ${tipoLabel}`);
340	
341	    setAplicados((prev) => [
342	      {
343	        itemId: targetReal.id,
344	        produtoNome: targetReal.produto_nome,
345	        uid: payload.uid,
346	        qty: scannedQty,
347	        embalagem: scannedEmb,
348	        tipoEmbalagem: scannedTipoEmb,
349	        qtyInterna: qtyEtiquetaReal,
350	        loteId: scannedLote,
351	        bipadoAt: Date.now(),
352	      },
353	      ...prev,
354	    ]);
355	    uidsLidosRef.current.add(payload.uid);
356	  };
357	
358	  const scanner = useEtiquetaScanner({
359	    enabled: isOpen,
360	    onScan: handleBip,
361	    onInvalid: () => {
362	      toast.error("QR ilegível");
363	    },
364	    onDuplicate: () => {
365	      playErrorSound();
366	      toast.error("Esta etiqueta já foi bipada");
367	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
368	    },
369	    cameraElementId: "picking-bip-camera",
370	    initialMode: defaultMode,
371	  });
372	
373	  // Progresso por item — caixas bipadas + un acumuladas
374	  const progressoPorItem = useMemo(() => {
375	    return items.map((item) => {
376	      const bipsItem = aplicados.filter((a) => a.itemId === item.id);
377	      const caixas = bipsItem.length;
378	      const unBipadas = bipsItem.reduce((acc, b) => acc + b.qty, 0);
379	      const unBaseInicial = bipsItem.length === 0 ? Number(item.quantidade_enviada || 0) : 0;
380	      const totalUn = unBipadas + unBaseInicial;
381	      const pedidoUn = item.quantidade || 0;
382	      const pct = pedidoUn > 0 ? Math.min(100, Math.round((totalUn / pedidoUn) * 100)) : 0;
383	      const status: "vazio" | "parcial" | "completo" | "excesso" =
384	        totalUn === 0 ? "vazio"
385	          : totalUn > pedidoUn ? "excesso"
386	          : totalUn >= pedidoUn ? "completo"
387	          : "parcial";
388	      return { item, caixas, unBipadas, totalUn, pedidoUn, pct, status };
389	    });
390	  }, [items, aplicados]);
391	
392	  const stats = useMemo(() => {
393	    const completos = progressoPorItem.filter((p) => p.status === "completo" || p.status === "excesso").length;
394	    const totalUnSolicitado = progressoPorItem.reduce((acc, p) => acc + p.pedidoUn, 0);
395	    const totalUnEnviado = progressoPorItem.reduce((acc, p) => acc + p.totalUn, 0);
396	    const totalCaixas = aplicados.length;
397	    return {
398	      completos,
399	      itensTotais: items.length,
400	      bipsAplicados: aplicados.length,
401	      totalCaixas,
402	      totalUnSolicitado,
403	      totalUnEnviado,
404	    };
405	  }, [items, aplicados, progressoPorItem]);
406	
407	  return (
408	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
409	      <DialogContent
410	        data-mia-modal="separar-com-bip"
411	        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none"
412	        onPointerDownOutside={(e) => e.preventDefault()}
413	        onInteractOutside={(e) => e.preventDefault()}
414	      >
415	        {/* Header */}
416	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
417	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
418	            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
419	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
420	            </Button>
421	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
422	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
423	            </div>
424	            <div className="min-w-0 flex-1">
425	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">
426	                Separar com bip
427	              </DialogTitle>
428	              <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
429	                Aponte o leitor pra cada caixa que vai entrar no pedido
430	              </p>
431	            </div>
432	          </div>
433	          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
434	            <button
435	              onClick={() => scanner.setScanMode("bluetooth")}
436	              aria-label="Scanner Bluetooth"
437	              className={cn(
438	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
439	                scanner.scanMode === "bluetooth"
440	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
441	                  : "text-muted-foreground hover:text-foreground"
442	              )}
443	            >
444	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
445	            </button>
446	            <button
447	              onClick={() => scanner.setScanMode("camera")}
448	              aria-label="Scanner por câmera"
449	              className={cn(
450	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
451	                scanner.scanMode === "camera"
452	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
453	                  : "text-muted-foreground hover:text-foreground"
454	              )}
455	            >
456	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
457	            </button>
458	          </div>
459	        </div>
460	
461	        {/* Stats — caixas + qty lado-a-lado.
462	            Label "Enviado" eh generica porque a requisicao pode ter items em unidades
463	            diferentes (caixa + kg). Detalhe por unidade fica no ItemProgress de cada item. */}
464	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
465	          <Stat label="Itens completos" value={`${stats.completos}/${stats.itensTotais}`} />
466	          <Stat label="Bipados" value={String(stats.totalCaixas)} icon={<Boxes className="w-3 h-3" />} />
467	          <Stat label="Enviado" value={`${stats.totalUnEnviado}/${stats.totalUnSolicitado}`} />
468	          <Stat label="Bips" value={String(stats.bipsAplicados)} />
469	        </div>
470	
471	        {/* Scanner input invisível (Bluetooth) */}
472	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
473	
474	        {/* Body */}
475	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
