export function matchBipItem<T extends BipMatchItem>(
  items: T[],
  scannedPid: number | null | undefined,
  scannedNome: string | null | undefined,
): T | null {
  if (scannedPid != null) {
    const byId = items.find((i) => i.masterId != null && i.masterId === scannedPid);
    if (byId) return byId;
  }
  const n = normalizeProdutoNome(scannedNome);
  if (n) {
    const byName = items.find((i) => normalizeProdutoNome(i.produto_nome) === n);
    if (byName) return byName;
  }
  return null;
}

input.new_string:
export function matchBipItem<T extends BipMatchItem>(
  items: T[],
  scannedPid: number | null | undefined,
  scannedNome: string | null | undefined,
): T | null {
  if (scannedPid != null) {
    const byId = items.find((i) => i.masterId != null && i.masterId === scannedPid);
    if (byId) return byId;
  }
  const n = normalizeProdutoNome(scannedNome);
  if (n) {
    // Ambiguidade: se 2+ linhas normalizam pro mesmo nome, NÃO adivinha — devolve
    // null pra virar "extra" visível (operador resolve), em vez de creditar a linha
    // errada. O caminho por masterId já blinda o caso canônico.
    const byName = items.filter((i) => normalizeProdutoNome(i.produto_nome) === n);
    if (byName.length === 1) return byName[0];
  }
  return null;
}

/**
 * Decisão pura de excesso: a nova quantidade ultrapassa o pedido?
 * Usada tanto no gate pré-RPC (UX: evita transicionar a etiqueta se cancelar)
 * quanto no recheck pós-RPC com o `scannedPid` autoritativo (L-R009 — pré-fetch
 * é UX, nunca fonte de verdade de validação quantitativa).
 */
export function excedePedido(
  pedido: number,
  base: number,
  incremento: number,
): { excede: boolean; nova: number; sobra: number } {
  const nova = base + incremento;
  const sobra = nova - pedido;
  return { excede: nova > pedido, nova, sobra };
}

