import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, waitFor, fireEvent, cleanup } from '@testing-library/react';
import { PickingBipModal, type PickingBipItem } from './PickingBipModal';
import { supabase } from '@/integrations/supabase/client';

/**
 * Testes de integração do núcleo stateful do fix de concorrência:
 *  - serialização (mutex) + acumulador autoritativo → sem lost update
 *  - "não encontrado" não engole o bip (vira extra visível)
 *  - casagem por nome quando masterId ausente (fix do "fica 0/N")
 *
 * O scanner Bluetooth é simulado disparando keydown global (e.code) + Enter,
 * exatamente como o leitor físico faz (UID-only QR).
 */

/** Simula a leitura de um UID pelo leitor Bluetooth (keydown por char + Enter). */
function bipUid(uid: string) {
  for (const ch of uid) {
    const code = /[0-9]/.test(ch) ? `Digit${ch}` : `Key${ch.toUpperCase()}`;
    fireEvent.keyDown(document, { code });
  }
  fireEvent.keyDown(document, { code: 'Enter' });
}

function mockRpc(pid: number, nome: string) {
  (supabase.rpc as unknown as { mockResolvedValue: (v: unknown) => void }).mockResolvedValue({
    data: {
      ok: true,
      etiqueta: {
        produto_master_id: pid,
        produto_nome_snapshot: nome,
        quantidade_interna: 1,
        tipo_embalagem: 'pote',
        lote_id: 'L1',
      },
    },
    error: null,
  });
}

const baseItem = (over: Partial<PickingBipItem>): PickingBipItem => ({
  id: 1,
  produto_nome: 'BOLO POTE BANOFFE',
  masterId: 1036,
  quantidade: 2,
  quantidade_enviada: '',
  coletado: false,
