    expect(onApply).not.toHaveBeenCalled();
  });

  it('casa por NOME quando o item não tem masterId resolvido (fix do "fica 0/N")', async () => {
    mockRpc(1057, 'CUBA COOKIE');
    const onApply = vi.fn().mockResolvedValue(undefined);
    render(
      <PickingBipModal
        isOpen
        onClose={() => {}}
        items={[
          // masterId AUSENTE — antes do fix, o bip não casava e ficava 0/N.
          baseItem({ id: 5, produto_nome: 'CUBA COOKIE', masterId: undefined, quantidade: 3 }),
